import 'dart:convert';
import 'dart:io';

import 'package:delve/api/events.dart';
import 'package:delve/api/models/models.dart';
import 'package:delve/api/protocol.dart';
import 'package:flutter_test/flutter_test.dart';

/// The app's view of the backend contract.
///
/// `contract.json` is a copy of `delve-backend/docs/contract.json`; `samples.json`
/// is generated by `tool/gen_contract_samples.py` with the backend's own
/// serializers. When the backend contract changes, copy the new file here,
/// regenerate the samples, and this test points at every model to update.
void main() {
  Map<String, Object?> load(String name) =>
      jsonDecode(File('test/fixtures/contract/$name').readAsStringSync())
          as Map<String, Object?>;
  final contract = load('contract.json');
  final samples = load('samples.json');
  Map<String, Object?> obj(Object? v) => v! as Map<String, Object?>;

  final shapes = obj(contract['shapes']);
  final ws = obj(contract['ws']);
  final sampleShapes = obj(samples['shapes']);
  final sampleEvents = obj(samples['events']);
  final connection = obj(samples['connection']);

  /// Key tree of a contract shape: `true` leaves, nested maps for objects.
  Object keyTree(Object? shape) => shape is Map<String, Object?>
      ? {for (final e in shape.entries) e.key: keyTree(e.value)}
      : true;

  /// Key tree of a JSON value, descending only where the contract does.
  Object jsonTree(Object? json, Object? like) =>
      like is Map<String, Object?> && json is Map<String, Object?>
      ? {for (final e in json.entries) e.key: jsonTree(e.value, like[e.key])}
      : true;

  group('REST', () {
    test('the app knows exactly the contract routes', () {
      final routes = {
        for (final r
            in (contract['rest']! as List<Object?>)
                .cast<Map<String, Object?>>())
          (r['method']! as String, r['path']! as String),
      };
      expect(ApiRoutes.all.toSet(), routes);
    });

    test('server contract revision is supported', () {
      expect(contract['api_revision'], greaterThanOrEqualTo(kMinApiRevision));
    });
  });

  group('shapes', () {
    final models =
        <String, Map<String, Object?> Function(Map<String, Object?>)>{
          'conversation': (j) => Conversation.fromJson(j).toJson(),
          'message': (j) => Message.fromJson(j).toJson(),
          'run': (j) => Run.fromJson(j).toJson(),
          'open_run': (j) => OpenRun.fromJson(j).toJson(),
          'approval': (j) => Approval.fromJson(j).toJson(),
          'tool_step': (j) => ToolStep.fromJson(j).toJson(),
          'card': (j) => AgentCard.fromJson(j).toJson(),
          'system': (j) => SystemInfo.fromJson(j).toJson(),
          'gpu': (j) => GpuInfo.fromJson(j).toJson(),
          'hermes_issue': (j) => HermesIssue.fromJson(j).toJson(),
          'schedule': (j) => Schedule.fromJson(j).toJson(),
          'brief_payload': (j) => Brief.fromJson(j).toJson(),
          'brief_incident': (j) => BriefIncident.fromJson(j).toJson(),
        };

    test('every contract shape has a model', () {
      expect(models.keys.toSet(), shapes.keys.toSet());
    });

    for (final name in models.keys) {
      test('$name: model keys equal the contract keys', () {
        final want = keyTree(shapes[name]);
        final sample = obj(sampleShapes[name]);
        expect(jsonTree(sample, want), want, reason: 'stale samples.json');
        // tool_step.approval is "approval|null" in the contract: a leaf here.
        final json = jsonDecode(jsonEncode(models[name]!(sample)));
        expect(jsonTree(json, want), want);
      });
    }

    test('nested approval of a tool step has the approval keys', () {
      final step = ToolStep.fromJson(obj(sampleShapes['tool_step']));
      expect(step.approval, isNotNull);
      expect(
        step.approval!.toJson().keys.toSet(),
        obj(shapes['approval']).keys.toSet(),
      );
    });

    test('models round-trip and keep values', () {
      final c = Conversation.fromJson(obj(sampleShapes['conversation']));
      expect(
        Conversation.fromJson(
          jsonDecode(jsonEncode(c.toJson())) as Map<String, Object?>,
        ),
        c,
      );
      expect(c.context.pct, 13.3);
      expect(c.totals.totalTokens, 25954);
      expect(c.createdAt.isUtc, isTrue);
      expect(c.preview, 'Kernel 7.2.11, 24 CPUs.');

      final m = Message.fromJson(obj(sampleShapes['message_user']));
      expect(m.clientMsgId, '0b8f3c52-7a1e-4d2b-9c61-2f5e8a7d3b10');

      final r = Run.fromJson(obj(sampleShapes['run']));
      expect(r.perf!['gen_tps'], 20.6);

      final s = ToolStep.fromJson(obj(sampleShapes['tool_step_plain']));
      expect((s.status, s.approval, s.durationS), ('running', null, null));
    });

    test('the system view keeps its values', () {
      final s = SystemInfo.fromJson(obj(sampleShapes['system']));
      expect(
        SystemInfo.fromJson(
          jsonDecode(jsonEncode(s.toJson())) as Map<String, Object?>,
        ),
        s,
      );
      expect((s.helper.ok, s.hermes.status), (true, 'degraded'));
      expect(s.hermes.issues.single.detail, '96% used');
      expect(s.hermes.since!.isUtc, isTrue);
      expect(
        (s.llama.model, s.llama.quant, s.llama.ctx, s.llama.slotsBusy),
        ('Qwen3.8-27B', 'IQ4_XS', 65536, 1),
      );
      expect(s.llama.genTps, 21.4);
      expect((s.queue.active, s.queue.queued), (1, 1));
      final g = s.gpus!.first;
      expect((g.memUsedMib, g.memTotalMib, g.powerW), (11381, 12282, 40.39));
    });

    test('schedules and the brief keep their values', () {
      final s = Schedule.fromJson(obj(sampleShapes['schedule']));
      expect(
        Schedule.fromJson(
          jsonDecode(jsonEncode(s.toJson())) as Map<String, Object?>,
        ),
        s,
      );
      expect((s.kind, s.cron, s.prompt), ('brief', '30 7 * * *', null));
      expect((s.description, s.lastStatus), ('At 07:30 every day', 'ok'));
      final p = Schedule.fromJson(obj(sampleShapes['schedule_prompt']));
      expect(
        (p.conversationMode, p.conversationId),
        ('fixed', 'c_5f2a9e1b7c3d4e6f'),
      );
      expect(p.lastStatus, isNull);

      final card = AgentCard.fromJson(obj(sampleShapes['card_brief']));
      final b = Brief.fromJson(card.payload);
      expect((b.uptimeS, b.openIncidents, b.updatesCount), (275400, 1, 44));
      expect(b.bootedAt!.isUtc, isTrue);
      expect(b.incidents.single.state, 'detected');
      expect((b.water!.levelCm, b.water!.trendCm24h), (98.0, -2.0));
      expect((b.llamaState, b.hermesState), ('running', 'degraded'));
      expect(b.missing, isEmpty);
    });

    test('REST/sync history messages carry their tool steps', () {
      final h = HistoryMessage.fromJson(obj(connection['history_message']));
      expect(h.message.id, 412);
      expect(h.toolSteps.single.tool, 'terminal');
    });

    test('devices/me carries push and the notification settings', () {
      final raw = obj(connection['device_me']);
      expect(raw.keys.toSet(), {
        'id',
        'name',
        'created_at',
        'last_seen_at',
        'fcm',
        'push',
        'notify',
      });
      final d = DeviceInfo.fromJson(raw);
      expect((d.fcm, d.push), (true, true));
      expect(
        d.notify,
        const NotifySettings(runDone: false),
        reason: 'run_done maps to runDone',
      );
      expect(
        obj(raw['notify']).keys.toSet(),
        const NotifySettings().toJson().keys.toSet(),
      );
      // an API 2 server: no push, the defaults
      final old = DeviceInfo.fromJson(
        {...raw}
          ..remove('push')
          ..remove('notify'),
      );
      expect((old.push, old.notify), (false, const NotifySettings()));
    });
  });

  group('WebSocket', () {
    final serverEvents = obj(ws['server_events']);

    test('the app knows every server event type', () {
      expect(ServerEvent.knownTypes, serverEvents.keys.toSet());
    });

    for (final type in serverEvents.keys) {
      test('$type parses', () {
        final data = obj(sampleEvents[type]);
        expect(
          data.keys.toSet(),
          (serverEvents[type]! as List<Object?>).toSet(),
          reason: 'stale samples.json',
        );
        final frame = IncomingFrame.parse(
          jsonDecode(jsonEncode({'type': type, 'seq': 7, 'data': data}))
              as Map<String, Object?>,
        );
        expect(frame, isA<ServerEvent>());
        expect(frame, isNot(isA<UnknownEvent>()));
        expect((frame as ServerEvent).seq, 7);
      });
    }

    test('event payloads land in the right fields', () {
      ServerEvent ev(String type) =>
          ServerEvent.fromData(type, 1, obj(sampleEvents[type]));
      final started = ev('run.started') as RunStarted;
      expect(started.queuedId, startsWith('q_'));
      expect(started.runId, startsWith('run_'));
      final ctx = ev('context.updated') as ContextUpdated;
      expect((ctx.tokens, ctx.max, ctx.isFinal), (8728, 65536, true));
      final req = ev('approval.request') as ApprovalRequested;
      expect(req.stepId, 97);
      expect(req.approval.choices, ['once', 'session', 'deny']);
      final sys = ev('system.updated') as SystemUpdated;
      expect(
        (sys.system.llama.status, sys.system.llama.intent),
        ('stopped', 'stopped'),
      );
      expect(sys.system.queue.queued, 2);
      final err = ev('error') as ServerError;
      expect(err.code, 'thinking_route_not_applied');
      final upd = ev('conversation.updated') as ConversationUpdated;
      expect(
        (upd.conversation.title, upd.conversation.context.pct),
        (null, null),
      );
    });

    test('unknown event types are kept, malformed known ones throw', () {
      final f = IncomingFrame.parse({
        'type': 'future.event',
        'seq': 3,
        'data': {'id': 'x'},
      });
      expect(f, isA<UnknownEvent>());
      expect(
        () => IncomingFrame.parse({
          'type': 'message.delta',
          'seq': 4,
          'data': {
            'conversation_id': 'c',
            'run_id': 'r',
            'message_id': 'x',
            'delta': '',
          },
        }),
        throwsFormatException,
      );
    });

    test('connection frames', () {
      expect((ws['connection_frames']! as List<Object?>).toSet(), {
        'hello.ok',
        'ack',
        'error',
        'pong',
        'keepalive',
      });
      final hello = IncomingFrame.parse({
        'type': 'hello.ok',
        'data': connection['hello.ok'],
      });
      expect(hello, isA<HelloOkFrame>());
      final h = (hello as HelloOkFrame).hello;
      expect(
        (h.epoch, h.seq, h.resyncRequired),
        ('9f8e7d6c5b4a3921', 1042, false),
      );
      expect(h.thinkingRoute!.ok, isTrue);

      final err = IncomingFrame.parse({
        'type': 'error',
        'id': 'f1',
        'data': {'code': 'invalid_choice', 'message': 'no'},
      });
      expect(err, isA<ErrorReply>());
      expect((err as ErrorReply).id, 'f1');
      expect(
        IncomingFrame.parse({
          'type': 'keepalive',
          'data': {'ts': 1.5},
        }),
        isA<KeepaliveFrame>(),
      );
      expect(
        IncomingFrame.parse({'type': 'pong', 'id': 'p', 'data': {}}),
        isA<PongFrame>(),
      );
      expect(
        IncomingFrame.parse({
          'type': 'ack',
          'id': 'a',
          'data': {'status': 'ok'},
        }),
        isA<AckFrame>(),
      );
    });

    test('meta and status parse, unknown keys ignored', () {
      final meta = ServerMeta.fromJson(obj(connection['meta']));
      expect(meta.apiRevision, contract['api_revision']);
      expect(meta.revision, 'eb4045ed6a94');
      final status = ServerStatus.fromJson(obj(connection['status']));
      expect((status.hermes, status.thinkingRoute), (null, null));
    });

    group('client frames match the contract', () {
      final frames = obj(ws['client_frames']);
      final full = <String, Map<String, Object?>>{
        'hello': ClientFrames.hello(
          id: '1',
          deviceToken: 't',
          lastSeq: 3,
          epoch: 'e',
        ),
        'chat.send': ClientFrames.chatSend(
          id: '2',
          text: 'hi',
          clientMsgId: 'u',
          conversationId: 'c',
          thinking: true,
        ),
        'conversation.set': ClientFrames.conversationSet(
          id: '3',
          conversationId: 'c',
          thinking: false,
          archived: true,
        ),
        'run.stop': ClientFrames.runStop(id: '4', runId: 'q_1'),
        'approval.respond': ClientFrames.approvalRespond(
          id: '5',
          requestId: 'r',
          choice: ApprovalChoice.once,
        ),
        'sync': ClientFrames.sync(
          id: '6',
          conversationId: 'c',
          afterMessageId: 10,
        ),
        'ping': ClientFrames.ping(id: '7'),
      };
      final minimal = <String, Map<String, Object?>>{
        'hello': ClientFrames.hello(id: '1', deviceToken: 't'),
        'chat.send': ClientFrames.chatSend(
          id: '2',
          text: 'hi',
          clientMsgId: 'u',
        ),
        'conversation.set': ClientFrames.conversationSet(
          id: '3',
          conversationId: 'c',
        ),
        'sync': ClientFrames.sync(id: '6', conversationId: 'c'),
      };

      test('every client frame type has a builder', () {
        expect(full.keys.toSet(), frames.keys.toSet());
      });

      for (final type in full.keys) {
        test(type, () {
          final spec = obj(frames[type]);
          final req = (spec['required']! as List<Object?>).toSet();
          final opt = (spec['optional']! as List<Object?>).toSet();
          final f = full[type]!;
          expect(f['type'], type);
          expect(obj(f['data']).keys.toSet(), {...req, ...opt});
          final m = minimal[type];
          if (m != null) expect(obj(m['data']).keys.toSet(), req);
        });
      }

      test('always is not a choice the app can send', () {
        expect(ApprovalChoice.values.map((c) => c.wire), [
          'once',
          'session',
          'deny',
        ]);
      });
    });
  });

  test('path templates are filled and encoded', () {
    expect(
      ApiRoutes.path(ApiRoutes.messages.$2, {'conversation_id': 'c_1'}),
      '/api/v1/conversations/c_1/messages',
    );
    expect(() => ApiRoutes.path(ApiRoutes.usage.$2), throwsArgumentError);
  });
}
